const BRANDS = [
  { t: 'App Store', cs: false }, { t: 'Apple Pay', cs: false }, { t: 'Facebook', cs: false },
  { t: 'Google Pay', cs: false }, { t: 'Love Language', cs: false }, { t: 'Mobitrace', cs: false },
  { t: 'My QR Code', cs: true }, { t: 'MyImage', cs: true },
  { t: 'MyQRCode.com', cs: true }, { t: 'Omnixo Apps EOOD', cs: false }, { t: 'PDF Help', cs: true },
  { t: 'QRcreate', cs: true }, { t: 'ResumeWise', cs: true }, { t: 'ScanPRO', cs: true },
  { t: 'UniCopy', cs: true }, { t: 'Chatbot Online', cs: false }, { t: 'RealChecker', cs: true }
];

const NO_REPEAT_LANG = ['id','ms','fil','vi','th','ko','ja','zh','zh_cn','zh_tw'];
const SKIP_CONSONANT_TRIPLE = ['de','nl','sv','no','nb','da','fi','et','hu','is','af'];
const SKIP_VOWEL_TRIPLE = ['fil','ro'];

const REPEAT_OK = {
  _global: ['st','nd','rd','th','ii','iii','iv','xx','ok','pc','tv','cd','id','no'],
  nl: ['je','jij','u','die','dat','het','om','door','in','uit','op','af','over','aan','bij','mee','na','toe','meer','zich','er','wat','als','nog','maar','of','te','is','was','heel','zo','een'],
  fr: ['vous','nous','se','si','plus','en','y','le','la','les','de','que','ne','tout','bien','tres','on','a'],
  de: ['die','das','sie','der','den','dem','was','wie','so','da','an','in','zu','mehr','nur','noch','sich','es','ist','sehr','man'],
  es: ['se','lo','que','mas','si','muy','ya','y','o','la','el','no','a'],
  it: ['che','si','la','ne','piu','molto','gia','e','a','ci','vi','piano','passo','appena','via','poco','mano','quasi'],
  pt: ['se','a','o','que','mais','ja','muito','e','so'],
  ro: ['la','sa','se','ce','mai','o','si','de','foarte','ca'],
  pl: ['to','w','i','ze','sie','tak','juz','bardzo','co'],
  cs: ['to','se','si','ze','tak','uz','moc','ve','co'],
  sk: ['to','sa','si','ze','tak','uz','vo','co'],
  sl: ['se','si','to','da','ze','ne','zelo','kaj'],
  hr: ['se','si','to','da','ne','vec','vrlo','sto'],
  sv: ['upp','for','som','till','om','av','i','pa','ut','in','an','mer','ju','sa','val','det'],
  da: ['for','som','til','om','af','i','pa','ud','ind','mer','jo','sa','vel','det'],
  no: ['for','som','til','om','av','i','pa','ut','inn','mer','jo','sa','vel','det'],
  nb: ['for','som','til','om','av','i','pa','ut','inn','mer','jo','sa','vel','det'],
  fi: ['on','ei','ja','se','niin','vain','jo','kun'],
  et: ['on','ei','ja','see','nii','ka','ju','kui'],
  lv: ['ir','un','ka','jau','loti','ta','gan'],
  lt: ['ir','jau','tik','labai','kad','tai'],
  hu: ['is','meg','csak','mar','nagyon','hogy','a'],
  el: ['που','να','το','θα','και','πιο','πολυ','τα','σε'],
  uk: ['що','не','і','та','дуже','вже','це'],
  tr: ['adim','kez','kere','tek','yavas','bir','cok','daha','iki','uc','bes','on','sik','azar','birer','arada','yer','zaman']
};

const LEGIT_TRIPLE = ['schifffahrt','rollladen','stilllegung','stillleben','brennnessel',
  'schneeeule','kaffeeersatz','kaffeeernte','betttuch','balletttanz','sauerstoffflasche',
  'fussballliga','nulllinie','volllast','helllicht','sperrrad','fetttropf','flussschiff',
  'kunststofffenster','sammelllinse','schlussstrich','stofffarbe','missstand','missstaende'];

const FOLD = { 'ı': 'i', 'İ': 'i', 'ß': 'ss', 'ł': 'l', 'ø': 'o', 'Ø': 'o', 'æ': 'ae', 'đ': 'd', 'Đ': 'd' };

function deaccent(s) {
  const t = String(s).normalize('NFD').replace(/\p{M}/gu, '');
  let o = '';
  for (const ch of t) { o += (FOLD[ch] !== undefined ? FOLD[ch] : ch); }
  return o;
}
function squash(s) { return deaccent(s).toLowerCase().replace(/[^\p{L}\p{Nd}]/gu, ''); }
function isVowelChar(c) { return 'aeiouy'.indexOf(deaccent(c).toLowerCase()) !== -1; }
function legitTriple(low) {
  for (const w of LEGIT_TRIPLE) { if (low.indexOf(w) !== -1) { return true; } }
  return false;
}
function stripNoise(s) {
  return String(s)
    .replace(/<[^>]*>/g, ' ')
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/\S+@\S+\.\S+/g, ' ')
    .replace(/\[%[^\]]*\]/g, ' ')
    .replace(/%\d+\$[a-zA-Z]/g, ' ')
    .replace(/%[sdioxfeguc@]/g, ' ')
    .replace(/\{\{[^}]*\}\}/g, ' ')
    .replace(/\{[^}]*\}/g, ' ')
    .replace(/\[[^\]]*\]/g, ' ')
    .replace(/&nbsp;/gi, '\u00A0')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&apos;/gi, "'")
    .replace(/&#0*39;/g, "'")
    .replace(/&[a-zA-Z]+;/g, '~')
    .replace(/&#\d+;/g, '~')
    .replace(/\$\w+/g, ' ')
    .replace(/:\w+:/g, ' ');
}
function tokenize(s) {
  const parts = String(s).split(/[^\p{L}\p{M}]+/u);
  const out = [];
  for (const p of parts) { if (p.length > 0) { out.push(p); } }
  return out;
}
function isAllUpper(t) { return t === t.toUpperCase() && /\p{L}/u.test(t); }
function isPseudo(iso) {
  const s = (iso || '').toLowerCase();
  return s === 'pst' || s.indexOf('pseudo') >= 0;
}
function lev(a, b) {
  const m = a.length, n = b.length;
  if (Math.abs(m - n) > 3) { return 99; }
  let prev = [];
  for (let j = 0; j <= n; j++) { prev.push(j); }
  for (let i = 1; i <= m; i++) {
    const cur = [i];
    for (let j = 1; j <= n; j++) {
      const cost = a.charAt(i - 1) === b.charAt(j - 1) ? 0 : 1;
      cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost));
    }
    prev = cur;
  }
  return prev[n];
}
function repeatAllowed(iso, word) {
  const w = deaccent(word).toLowerCase();
  if (REPEAT_OK._global.indexOf(w) !== -1) { return true; }
  const list = REPEAT_OK[iso];
  if (list && list.indexOf(w) !== -1) { return true; }
  if (list && list.indexOf(String(word).toLowerCase()) !== -1) { return true; }
  return false;
}
function trimEdges(x) { return String(x).replace(/^[^\p{L}\p{Nd}]+/u, '').replace(/[^\p{L}\p{Nd}]+$/u, ''); }

function brandFindings(target, source, srcTokens) {
  const found = {};
  const findings = [];
  const clean = stripNoise(target);
  const tgtTokens = clean.split(/\s+/).filter(function (x) { return x.length > 0; });
  const srcSquash = squash(source);

  for (const b of BRANDS) {
    const bs = squash(b.t);
    if (bs.length < 5) { continue; }
    if (srcSquash.indexOf(bs) === -1) { continue; }
    const maxSpan = b.t.split(/\s+/).length + 1;
    const tol = bs.length <= 8 ? 1 : 2;
    let matched = null;
    let best = null;

    for (let i = 0; i < tgtTokens.length; i++) {
      for (let span = 1; span <= maxSpan && i + span <= tgtTokens.length; span++) {
        const cand = trimEdges(tgtTokens.slice(i, i + span).join(' '));
        const cs2 = squash(cand);
        if (cs2.length === 0) { continue; }
        if (cs2 === bs) { if (!matched) { matched = cand; } continue; }
        if (srcTokens[cs2]) { continue; }
        if (cs2.length > bs.length && cs2.indexOf(bs) === 0) { continue; }
        if (cs2.length > bs.length && cs2.indexOf(bs) === cs2.length - bs.length) { continue; }
        if (b.t.indexOf('.') === -1 && /\.[a-z]{2,6}$/i.test(cand)) { continue; }
        const d = lev(cs2, bs);
        if (d > 0 && d <= tol) { if (!best || d < best.d) { best = { d: d, cand: cand }; } }
      }
      if (matched) { break; }
    }

    if (matched) {
      if (b.cs && b.t.indexOf('.') === -1 && matched !== b.t) {
        const sig = 'case|' + matched + '|' + b.t;
        if (!found[sig]) { found[sig] = 1; findings.push({ rule: 'brand_case', token: matched, expected: b.t }); }
      }
      continue;
    }
    if (best) {
      const sig = 'miss|' + best.cand;
      if (!found[sig]) { found[sig] = 1; findings.push({ rule: 'brand_misspelled', token: best.cand, expected: b.t }); }
    }
  }
  return findings;
}

function findTypos(text, isoRaw, srcSet) {
  const iso = (isoRaw || '').toLowerCase();
  const findings = [];
  const clean = stripNoise(text);
  const skipCons = SKIP_CONSONANT_TRIPLE.indexOf(iso) !== -1;
  const skipVow = SKIP_VOWEL_TRIPLE.indexOf(iso) !== -1;

  for (const tok of tokenize(clean)) {
    const low = tok.toLowerCase();
    if (srcSet[low]) { continue; }
    if (tok.length >= 4 && !isAllUpper(tok) && !legitTriple(deaccent(low))) {
      const m = tok.match(/(\p{L})\1\1/u);
      if (m) {
        const vowel = isVowelChar(m[1]);
        if (!((vowel && skipVow) || (!vowel && skipCons))) {
          findings.push({ rule: 'triple_letter', token: tok, expected: '' });
          continue;
        }
      }
    }
    if (/\p{Script=Latin}/u.test(tok) && /\p{Script=Cyrillic}|\p{Script=Greek}/u.test(tok)) {
      findings.push({ rule: 'mixed_script', token: tok, expected: '' });
      continue;
    }
  }

  if (NO_REPEAT_LANG.indexOf(iso) === -1) {
    const re = /(?<![\p{L}\p{Nd}\-\u2011\u2013_])(\p{L}{2,})[ \u00A0]+\1(?![\p{L}\p{Nd}\-\u2011\u2013_])/giu;
    let mm;
    while ((mm = re.exec(clean)) !== null) {
      const w1 = mm[1];
      if (/^(.)\1+$/u.test(w1)) { continue; }
      if (repeatAllowed(iso, w1)) { continue; }
      findings.push({ rule: 'repeated_word', token: mm[0].replace(/\s+/g, ' ').trim(), expected: '' });
    }
  }
  return findings;
}

function keyName(k) {
  const n = k.key_name;
  if (typeof n === 'string') { return n; }
  if (n && typeof n === 'object') { return n.web || n.other || n.ios || n.android || String(k.key_id); }
  return String(k.key_id);
}

const meta = $('Page Input').first().json;
const baseLang = (meta.base_lang || 'en').toLowerCase();
const r = $input.first().json || {};
const ok = r.statusCode === 200;
const keys = (ok && r.body && r.body.keys) ? r.body.keys : [];
const rows = [];
let examined = 0;

for (const k of keys) {
  if (k.is_archived) { continue; }
  examined++;
  const trs = k.translations || [];
  const srcSet = {};
  const srcSquashSet = {};
  let srcText = '';
  for (const tr of trs) {
    if ((tr.language_iso || '').toLowerCase() === baseLang) {
      srcText = typeof tr.translation === 'string' ? tr.translation : '';
      for (const t of tokenize(stripNoise(srcText))) {
        srcSet[t.toLowerCase()] = 1;
        srcSquashSet[squash(t)] = 1;
      }
    }
  }
  for (const tr of trs) {
    const iso = (tr.language_iso || '').toLowerCase();
    if (iso === baseLang) { continue; }
    if (isPseudo(iso)) { continue; }
    if (tr.is_untranslated) { continue; }
    const v = tr.translation;
    if (typeof v !== 'string' || v.length === 0) { continue; }
    const hits = findTypos(v, iso, srcSet).concat(brandFindings(v, srcText, srcSquashSet));
    for (const h of hits) {
      rows.push({
        project: meta.project_name,
        project_id: meta.project_id,
        lang: iso,
        key: keyName(k),
        key_id: k.key_id,
        rule: h.rule,
        token: h.token,
        expected: h.expected || '',
        target: v.length > 300 ? v.slice(0, 300) + '…' : v,
        source: srcText.length > 300 ? srcText.slice(0, 300) + '…' : srcText,
        is_reviewed: tr.is_reviewed ? 1 : 0
      });
    }
  }
}

return [{ json: {
  project: meta.project_name,
  project_id: meta.project_id,
  page: meta.page,
  ok: ok,
  status: r.statusCode,
  keys_examined: examined,
  finding_count: rows.length,
  rows: rows
}}];
